def solve(s) -> int:
    """Convert a Roman numeral to an integer.
    Handles uppercase, lowercase, bytes and ignores surrounding whitespace.
    """
    # Normalize input to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            s = s.decode('utf-8', errors='ignore')
    if not isinstance(s, str):
        # Non‑string, non‑bytes input: treat as empty numeral
        return 0
    s = s.strip().upper()
    if not s:
        return 0
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
             'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        val = roman[s[i]]
        if i + 1 < n and roman[s[i + 1]] > val:
            total += roman[s[i + 1]] - val
            i += 2
        else:
            total += val
            i += 1
    return total

