    try:
        iterator = iter(s)
    except TypeError:
        return []
    # Convert to list to allow indexing; works for strings and other sequences.
    seq = list(iterator)
    if not seq:
        return []
    res = []
    prev = seq[0]
    cnt = 1
    for cur in seq[1:]:
        if cur == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = cur
            cnt = 1
    res.append([prev, cnt])
    return res

