def solve(s) -> int:
    """Convert a Roman numeral to an integer.
    Accepts strings (any case), bytes, bytearray, or iterables of single-character strings.
    Leading/trailing whitespace is ignored. Internal whitespace makes the input invalid.
    Raises ValueError if the input contains characters other than I,V,X,L,C,D,M after stripping.
    Returns 0 for empty input.
    """
    # Normalize bytes/bytearray to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            s = s.decode('utf-8', errors='ignore')
    # Convert non-string iterables to string
    if isinstance(s, str):
        txt = s
    else:
        try:
            txt = ''.join(str(ch) for ch in s)
        except Exception:
            raise ValueError('Invalid input')
    # Strip outer whitespace and uppercase
    txt = txt.strip().upper()
    if not txt:
        return 0
    # Internal whitespace is not allowed
    if any(ch.isspace() for ch in txt):
        raise ValueError('Invalid whitespace in numeral')
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
             'C': 100, 'D': 500, 'M': 1000}
    # Validate characters
    for ch in txt:
        if ch not in roman:
            raise ValueError('Invalid character')
    total = 0
    i = 0
    n = len(txt)
    while i < n:
        val = roman[txt[i]]
        if i + 1 < n and roman[txt[i + 1]] > val:
            total += roman[txt[i + 1]] - val
            i += 2
        else:
            total += val
            i += 1
    return total

