    if not tokens:
        return 0
    stack = []
    for t in tokens:
        if t not in '+-*/':
            stack.append(int(t))
        else:
            if len(stack) < 2:
                raise ValueError('Insufficient operands')
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # '/'
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Truncate toward zero without using float division
                sign = (a * b) >= 0
                q = abs(a) // abs(b)
                stack.append(q if sign else -q)
    return stack[-1] if stack else 0

