def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    The grid may be empty or have rows of different lengths. Cells are
    connected vertically and horizontally.
    """
    if not grid:
        return 0
    n = len(grid)
    visited = [set() for _ in range(n)]  # visited columns per row
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= n:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if (j) in visited[i] or grid[i][j] == 0:
                continue
            visited[i].add(j)
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    islands = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and j not in visited[i]:
                dfs(i, j)
                islands += 1
    return islands

