def solve(grid):
    """Count the number of islands of 1s in a possibly irregular grid.
    An island is a group of horizontally or vertically adjacent cells containing 1.
    The function does not modify the input grid.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def is_land(i, j):
        # Guard against out-of-range rows/cols handled by caller
        return grid[i][j] == 1
    def dfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore four directions
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and (ni, nj) not in visited:
                    if grid[ni][nj] == 1:
                        stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                islands += 1
    return islands

