    Handles strings, bytes/bytearray (decoded as UTF-8), and any other iterable of hashable items.
    Returns a list of [element, count] pairs. Non‑iterable inputs yield [] .
    """
    # Decode bytes-like objects to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            return []
    # Try to get an iterator from s
    try:
        it = iter(s)
    except TypeError:
        return []
    # Obtain first element
    try:
        prev = next(it)
    except StopIteration:
        return []
    cnt = 1
    res = []
    for cur in it:
        if cur == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = cur
            cnt = 1
